import { Static } from 'ivue/extras';

// Response construction for every endpoint — one place decides headers,
// CORS reach, and error shape.
class $Http {
  static json(payload: unknown, status = 200): Response {
    return new Response(JSON.stringify(payload), {
      status,
      headers: { 'content-type': 'application/json' },
    });
  }

  static html(markup: string, status = 200): Response {
    return new Response(markup, {
      status,
      headers: { 'content-type': 'text/html; charset=utf-8' },
    });
  }

  static notFound(): Response {
    return new Response('Not found', { status: 404 });
  }

  // CORS is granted to the SITE origin only — the public subscribe form.
  // The admin dashboard is same-origin (served by this Worker's assets)
  // or proxied server-side by the local dev server, so /admin/* never
  // needs a CORS grant.
  static withCors(response: Response, env: Env): Response {
    response.headers.set('access-control-allow-origin', env.SITE_ORIGIN);
    response.headers.set('access-control-allow-methods', 'POST, OPTIONS');
    response.headers.set('access-control-allow-headers', 'content-type');
    return response;
  }

  static async readJsonBody<Body extends object>(
    request: Request,
  ): Promise<Partial<Body>> {
    return (await request.json().catch(() => ({}))) as Partial<Body>;
  }

  static nowSeconds(): number {
    return Math.floor(Date.now() / 1000);
  }
}

export namespace Http {
  export const $Class = Static($Http);
  export let Class = $Class;
}

import { Static } from 'ivue/extras';

// Secret comparison and unsubscribe-link signing. Every credential check
// in the Worker flows through the one timing-safe comparison here.
class $Security {
  // Compare secrets without a timing side-channel: hash both to fixed
  // size (no length leak), then constant-time compare.
  static async timingSafeEqualStrings(
    provided: string,
    expected: string,
  ): Promise<boolean> {
    const encoder = new TextEncoder();
    const [providedHash, expectedHash] = await Promise.all([
      crypto.subtle.digest('SHA-256', encoder.encode(provided)),
      crypto.subtle.digest('SHA-256', encoder.encode(expected)),
    ]);
    return crypto.subtle.timingSafeEqual(providedHash, expectedHash);
  }

  // Bearer [redacted] — /broadcast, /drip, and the whole /admin surface.
  static async bearerAuthorized(request: Request, env: Env): Promise<boolean> {
    const authorization = [redacted]'authorization') ?? '';
    return this.timingSafeEqualStrings(
      authorization,
      `Bearer ${env.ADMIN_SECRET}`,
    );
  }

  // Basic [redacted]:ADMIN_SECRET — the Postmark webhook's credential.
  static async basicAuthorized(request: Request, env: Env): Promise<boolean> {
    const authorization = [redacted]'authorization') ?? '';
    return this.timingSafeEqualStrings(
      authorization,
      `Basic ${btoa(`postmark:${env.ADMIN_SECRET}`)}`,
    );
  }

  static async unsubscribeToken(address: string, env: Env): Promise<string> {
    const key = await crypto.subtle.importKey(
      'raw',
      new TextEncoder().encode(env.ADMIN_SECRET),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign'],
    );
    const signature = await crypto.subtle.sign(
      'HMAC',
      key,
      new TextEncoder().encode(address),
    );
    return [...new Uint8Array(signature)]
      .map((byte) => byte.toString(16).padStart(2, '0'))
      .join('');
  }

  static async unsubscribeUrl(address: string, env: Env): Promise<string> {
    const token = await this.unsubscribeToken(address, env);
    return `${env.WORKER_ORIGIN}/unsubscribe?email=${encodeURIComponent(address)}&token=${token}`;
  }
}

export namespace Security {
  export const $Class = Static($Security);
  export let Class = $Class;
}

import { Static } from 'ivue/extras';

// Cloudflare Turnstile verification for the public subscribe form.
// Fails closed: any transport error, malformed token, or hostname/action
// mismatch counts as a bot.
class $Turnstile {
  static get SITEVERIFY_URL() {
    return 'https://challenges.cloudflare.com/turnstile/v0/siteverify';
  }

  static get EXPECTED_ACTION() {
    return 'newsletter';
  }

  static get MAXIMUM_TOKEN_LENGTH() {
    return 2048;
  }

  static async verify(
    token: string | undefined,
    clientIp: string | null,
    env: Env,
  ): Promise<boolean> {
    if (
      typeof token !== 'string' ||
      token.length === 0 ||
      token.length > this.MAXIMUM_TOKEN_LENGTH
    )
      return false;
    const expectedHostnames = new Set(
      (env.TURNSTILE_HOSTNAMES ?? '')
        .split(',')
        .map((hostname) => hostname.trim())
        .filter(Boolean),
    );
    if (expectedHostnames.size === 0) return false;
    try {
      const response = await fetch(this.SITEVERIFY_URL, {
        method: 'POST',
        headers: { 'content-type': 'application/x-www-form-urlencoded' },
        signal: AbortSignal.timeout(10_000),
        body: new URLSearchParams({
          // trim: a stray newline from `secret put` malforms the request
          secret: (env.TURNSTILE_SECRET ?? '').trim(),
          response: token.trim(),
          ...(clientIp ? { remoteip: clientIp } : {}),
        }),
      });
      if (!response.ok)
        throw new Error(
          `siteverify ${response.status}: ${(await response.text()).slice(0, 300)}`,
        );
      const result = (await response.json()) as {
        success: boolean;
        action?: string;
        hostname?: string;
        'error-codes'?: string[];
      };
      const verdict =
        result.success &&
        result.action === this.EXPECTED_ACTION &&
        expectedHostnames.has(result.hostname ?? '');
      if (!verdict) {
        console.error(
          JSON.stringify({
            event: 'turnstile_rejected',
            success: result.success,
            errorCodes: result['error-codes'] ?? [],
            action: result.action ?? null,
            hostname: result.hostname ?? null,
          }),
        );
      }
      return verdict;
    } catch (error) {
      console.error(
        JSON.stringify({
          event: 'turnstile_verify_failed',
          error: String(error),
        }),
      );
      return false; // fail closed
    }
  }
}

export namespace Turnstile {
  export const $Class = Static($Turnstile);
  export let Class = $Class;
}

import { Static } from 'ivue/extras';

// The post catalog. Email CONTENT is rendered at SITE build time
// (docs_v2/scripts/blog-email-renderer.mjs) and rides blog-index.json —
// this module only fetches and filters it. Template changes therefore
// ship via a site push, never a Worker deploy.
class $Posts {
  static async load(env: Env): Promise<Post[]> {
    const response = await fetch(`${env.SITE_ORIGIN}/blog-index.json`);
    if (!response.ok) throw new Error(`blog-index.json ${response.status}`);
    const posts = (await response.json()) as Post[];
    // deploy-order skew guard: a Worker newer than the deployed site would
    // read posts without emailHtml — skip them loudly instead of throwing
    const ready = posts.filter((post) => typeof post.emailHtml === 'string');
    if (ready.length < posts.length) {
      console.error(
        JSON.stringify({
          event: 'posts_missing_email_html',
          missing: posts.length - ready.length,
          hint: 'deploy the site (blog-index.json is stale)',
        }),
      );
    }
    return ready; // sorted oldest-first by the generator
  }

  static find(posts: Post[], slug: string): Post | undefined {
    return posts.find((candidate) => candidate.slug === slug);
  }

  // The catalog without email bodies — what list views and pickers need;
  // emailHtml is tens of kilobytes per post and stays server-side.
  static summaries(posts: Post[]): PostSummary[] {
    return posts.map(({ emailHtml: _emailHtml, ...summary }) => summary);
  }
}

export namespace Posts {
  export const $Class = Static($Posts);
  export let Class = $Class;
}

export interface Post {
  slug: string;
  title: string;
  description: string;
  url: string;
  date: string | null;
  timestamp: number;
  // the complete email body, rendered at site build time; one
  // {{UNSUBSCRIBE_URL}} placeholder remains for the Worker to fill
  emailHtml: string;
}

export type PostSummary = Omit<Post, 'emailHtml'>;

import { Static } from 'ivue/extras';
import { Http } from '../platform/Http';

// The audience layer — subscribers and the global suppression table.
// D1 is the single source of truth (Postmark has no contact-list
// product); a subscriber row belongs to one list, the same email may
// join several lists, and an unsubscribe suppresses the ADDRESS across
// every list — matching Postmark's per-address suppression model.
class $Audience {
  static get DEFAULT_LIST() {
    return 'newsletter';
  }

  static get PAGE_LIMIT_MAXIMUM() {
    return 200;
  }

  // Active recipients of one list: subscribed and not suppressed.
  static async active(env: Env, list: string): Promise<Subscriber[]> {
    const { results } = await env.DB.prepare(
      'SELECT email, name FROM subscribers WHERE list = ? ' +
        'AND email NOT IN (SELECT email FROM unsubscribes)',
    )
      .bind(list)
      .all<Subscriber>();
    return results;
  }

  // Subscribe (public form or admin add). A returning subscriber cancels
  // any previous unsubscribe — the sequence RESUMES, it never restarts,
  // because the sends ledger survives.
  static async enroll(
    env: Env,
    address: string,
    name: string,
    list: string,
  ): Promise<void> {
    await env.DB.batch([
      env.DB.prepare(
        'INSERT INTO subscribers (email, list, name, subscribed_at) VALUES (?, ?, ?, ?) ' +
          'ON CONFLICT(email, list) DO UPDATE SET name = excluded.name',
      ).bind(address, list, name, Http.Class.nowSeconds()),
      env.DB.prepare('DELETE FROM unsubscribes WHERE email = ?').bind(address),
    ]);
  }

  static async suppress(env: Env, address: string): Promise<void> {
    await env.DB.prepare(
      'INSERT OR REPLACE INTO unsubscribes (email, unsubscribed_at) VALUES (?, ?)',
    )
      .bind(address, Http.Class.nowSeconds())
      .run();
  }

  static async unsuppress(env: Env, address: string): Promise<void> {
    await env.DB.prepare('DELETE FROM unsubscribes WHERE email = ?')
      .bind(address)
      .run();
  }

  static async suppressMany(env: Env, addresses: string[]): Promise<void> {
    if (!addresses.length) return;
    const timestamp = Http.Class.nowSeconds();
    await env.DB.batch(
      addresses.map((address) =>
        env.DB.prepare(
          'INSERT OR REPLACE INTO unsubscribes (email, unsubscribed_at) VALUES (?, ?)',
        ).bind(address, timestamp),
      ),
    );
  }

  static async unsuppressMany(env: Env, addresses: string[]): Promise<void> {
    if (!addresses.length) return;
    await env.DB.batch(
      addresses.map((address) =>
        env.DB.prepare('DELETE FROM unsubscribes WHERE email = ?').bind(
          address,
        ),
      ),
    );
  }

  // Remove addresses from the audience entirely (every list). With
  // purgeSends the ledger rows go too — the address would be re-dripped
  // from the beginning if it ever re-subscribes.
  static async removeMany(
    env: Env,
    addresses: string[],
    purgeSends: boolean,
  ): Promise<void> {
    if (!addresses.length) return;
    const statements = addresses.flatMap((address) => [
      env.DB.prepare('DELETE FROM subscribers WHERE email = ?').bind(address),
      env.DB.prepare('DELETE FROM unsubscribes WHERE email = ?').bind(address),
      ...(purgeSends
        ? [env.DB.prepare('DELETE FROM sends WHERE email = ?').bind(address)]
        : []),
    ]);
    await env.DB.batch(statements);
  }

  // One page of the audience with per-subscriber aggregates — what the
  // dashboard table renders. Search matches email or name.
  static async page(
    env: Env,
    query: AudiencePageQuery,
  ): Promise<AudiencePage> {
    const list = query.list ?? '';
    const search = (query.search ?? '').trim();
    const searchPattern = `%${search}%`;
    const limit = Math.min(
      Math.max(1, query.limit ?? 50),
      this.PAGE_LIMIT_MAXIMUM,
    );
    const offset = Math.max(0, query.offset ?? 0);
    const whereClause =
      "WHERE (?1 = '' OR subscriber.list = ?1) " +
      "AND (?2 = '' OR subscriber.email LIKE ?3 OR subscriber.name LIKE ?3)";
    const [{ results: rows }, totalRow] = await Promise.all([
      env.DB.prepare(
        'SELECT subscriber.email, subscriber.list, subscriber.name, ' +
          'subscriber.subscribed_at AS subscribedAt, ' +
          'suppression.unsubscribed_at AS unsubscribedAt, ' +
          '(SELECT COUNT(*) FROM sends WHERE sends.email = subscriber.email) AS sendCount, ' +
          '(SELECT MAX(sent_at) FROM sends WHERE sends.email = subscriber.email) AS lastSentAt ' +
          'FROM subscribers subscriber ' +
          'LEFT JOIN unsubscribes suppression ON suppression.email = subscriber.email ' +
          whereClause +
          ' ORDER BY subscriber.subscribed_at DESC, subscriber.email LIMIT ?4 OFFSET ?5',
      )
        .bind(list, search, searchPattern, limit, offset)
        .all<SubscriberRow>(),
      env.DB.prepare(
        'SELECT COUNT(*) AS total FROM subscribers subscriber ' + whereClause,
      )
        .bind(list, search, searchPattern)
        .first<{ total: number }>(),
    ]);
    return { total: totalRow?.total ?? 0, rows, limit, offset };
  }

  // Every membership row for one address, plus its suppression state.
  static async memberships(
    env: Env,
    address: string,
  ): Promise<SubscriberRow[]> {
    const { results } = await env.DB.prepare(
      'SELECT subscriber.email, subscriber.list, subscriber.name, ' +
        'subscriber.subscribed_at AS subscribedAt, ' +
        'suppression.unsubscribed_at AS unsubscribedAt, ' +
        '(SELECT COUNT(*) FROM sends WHERE sends.email = subscriber.email) AS sendCount, ' +
        '(SELECT MAX(sent_at) FROM sends WHERE sends.email = subscriber.email) AS lastSentAt ' +
        'FROM subscribers subscriber ' +
        'LEFT JOIN unsubscribes suppression ON suppression.email = subscriber.email ' +
        'WHERE subscriber.email = ?',
    )
      .bind(address)
      .all<SubscriberRow>();
    return results;
  }

  static async lists(env: Env): Promise<ListSummary[]> {
    const { results } = await env.DB.prepare(
      'SELECT list, COUNT(*) AS members, ' +
        'SUM(CASE WHEN email NOT IN (SELECT email FROM unsubscribes) THEN 1 ELSE 0 END) AS active ' +
        'FROM subscribers GROUP BY list ORDER BY list',
    ).all<ListSummary>();
    return results;
  }

  static async signupsByDay(env: Env, days: number): Promise<DayCount[]> {
    const since = Http.Class.nowSeconds() - days * 86_400;
    const { results } = await env.DB.prepare(
      "SELECT date(subscribed_at, 'unixepoch') AS day, COUNT(*) AS count " +
        'FROM subscribers WHERE subscribed_at >= ? GROUP BY day ORDER BY day',
    )
      .bind(since)
      .all<DayCount>();
    return results;
  }
}

