export interface PostSendStats {
  slug: string;
  sendCount: number;
  lastSentAt: number;
}

import { Static } from 'ivue/extras';
import { Http } from '../platform/Http';
import { Security } from '../platform/Security';
import { Ledger } from '../audience/Ledger';
import type { Post } from '../content/Posts';
import type { Subscriber } from '../audience/Audience';

// Postmark delivery — batch API on the broadcast message stream. Only an
// accepted message (ErrorCode 0) is written to the sends ledger, so a
// failed batch or a rejected recipient retries on the next pass instead
// of being falsely marked sent.
class $Delivery {
  static get POSTMARK_BATCH_URL() {
    return 'https://api.postmarkapp.com/email/batch';
  }

  // Postmark accepts up to 500 messages per batch call; batching keeps
  // subrequests far under the Workers free-plan cap (50/invocation).
  static get SEND_BATCH_SIZE() {
    return 500;
  }

  static async sendPost(
    env: Env,
    post: Post,
    recipients: Subscriber[],
  ): Promise<DeliveryReport> {
    let delivered = 0;
    const outcomes: RecipientOutcome[] = [];
    for (
      let start = 0;
      start < recipients.length;
      start += this.SEND_BATCH_SIZE
    ) {
      const batch = recipients.slice(start, start + this.SEND_BATCH_SIZE);
      const messages = [];
      for (const recipient of batch) {
        const unsubscribe = await Security.Class.unsubscribeUrl(
          recipient.email,
          env,
        );
        messages.push({
          From: `${env.SENDER_NAME} <${env.SENDER_EMAIL}>`,
          ReplyTo: env.REPLY_TO,
          To: recipient.email,
          Subject: post.title,
          HtmlBody: post.emailHtml.replaceAll(
            '{{UNSUBSCRIBE_URL}}',
            unsubscribe,
          ),
          MessageStream: env.POSTMARK_STREAM,
          Headers: [
            { Name: 'List-Unsubscribe', Value: `<${unsubscribe}>` },
            {
              Name: 'List-Unsubscribe-Post',
              Value: 'List-Unsubscribe=One-Click',
            },
          ],
        });
      }
      const response = await fetch(this.POSTMARK_BATCH_URL, {
        method: 'POST',
        headers: {
          'X-Postmark-Server-Token': env.POSTMARK_SERVER_TOKEN,
          'content-type': 'application/json',
          accept: 'application/json',
        },
        body: JSON.stringify(messages),
      });
      if (!response.ok) {
        console.error(
          JSON.stringify({
            event: 'postmark_batch_failed',
            status: response.status,
            body: await response.text(),
          }),
        );
        for (const recipient of batch)
          outcomes.push({
            email: recipient.email,
            errorCode: response.status,
            message: 'Postmark batch call failed — will retry next run',
          });
        continue; // ledger stays unwritten — this batch retries next run
      }
      // per-message results: ErrorCode 0 = accepted; anything else (e.g.
      // 406 inactive recipient) is logged and NOT written to the ledger
      const results = (await response.json()) as PostmarkOutcome[];
      const timestamp = Http.Class.nowSeconds();
      const ledgerEntries = [];
      for (const [index, outcome] of results.entries()) {
        outcomes.push({
          email: batch[index].email,
          errorCode: outcome.ErrorCode,
          message: outcome.Message,
        });
        if (outcome.ErrorCode === 0) {
          ledgerEntries.push({
            email: batch[index].email,
            slug: post.slug,
            sentAt: timestamp,
          });
          delivered++;
        } else {
          console.error(
            JSON.stringify({
              event: 'postmark_message_rejected',
              recipient: batch[index].email,
              code: outcome.ErrorCode,
              message: outcome.Message,
            }),
          );
        }
      }
      await Ledger.Class.record(env, ledgerEntries);
    }
    return { delivered, outcomes };
  }
}

export namespace Delivery {
  export const $Class = Static($Delivery);
  export let Class = $Class;
}

export interface PostmarkOutcome {
  ErrorCode: number;
  Message: string;
}

export interface RecipientOutcome {
  email: string;
  errorCode: number;
  message: string;
}

export interface DeliveryReport {
  delivered: number;
  outcomes: RecipientOutcome[];
}

import { Static } from 'ivue/extras';
import { Http } from '../platform/Http';
import { Posts } from '../content/Posts';
import { Audience } from '../audience/Audience';
import { Ledger } from '../audience/Ledger';
import { Delivery } from './Delivery';
import type { Post } from '../content/Posts';
import type { Subscriber } from '../audience/Audience';
import type { SendRow } from '../audience/Ledger';

// The drip: each due subscriber receives their oldest unsent post, at
// most one email per CADENCE_HOURS. `plan()` is the pure decision —
// the cron, the /drip endpoint, and the dashboard's drip preview all
// read the same plan, so what the preview shows IS what the cron does.
class $Drip {
  static plan(
    posts: Post[],
    recipients: Subscriber[],
    sendRows: SendRow[],
    cadenceSeconds: number,
    now: number,
  ): DripPlanEntry[] {
    const sentByEmail = new Map<string, Set<string>>();
    const lastSentByEmail = new Map<string, number>();
    for (const row of sendRows) {
      let sentSet = sentByEmail.get(row.email);
      if (!sentSet) {
        sentSet = new Set();
        sentByEmail.set(row.email, sentSet);
      }
      sentSet.add(row.slug);
      lastSentByEmail.set(
        row.email,
        Math.max(lastSentByEmail.get(row.email) ?? 0, row.sentAt),
      );
    }
    return recipients.map((recipient) => {
      const sent = sentByEmail.get(recipient.email) ?? new Set();
      const nextPost = posts.find((candidate) => !sent.has(candidate.slug));
      const lastSentAt = lastSentByEmail.get(recipient.email) ?? 0;
      const dueAt = lastSentAt + cadenceSeconds;
      return {
        email: recipient.email,
        name: recipient.name,
        nextSlug: nextPost?.slug ?? null,
        sentCount: sent.size,
        lastSentAt: lastSentAt || null,
        dueAt: lastSentAt ? dueAt : now,
        sendNow: Boolean(nextPost) && now >= dueAt,
      };
    });
  }

  // One full pass: plan, group due subscribers by the post they are
  // owed, one batched send per slug. Drips the DEFAULT list only —
  // other lists are broadcast/targeted-send audiences.
  static async run(env: Env): Promise<number> {
    const posts = await Posts.Class.load(env); // oldest first
    const recipients = await Audience.Class.active(
      env,
      Audience.Class.DEFAULT_LIST,
    );
    if (!posts.length || !recipients.length) return 0;

    const sendRows = await Ledger.Class.allRows(env);
    const cadenceSeconds = Number(env.CADENCE_HOURS) * 3600;
    const entries = this.plan(
      posts,
      recipients,
      sendRows,
      cadenceSeconds,
      Http.Class.nowSeconds(),
    );

    const queueBySlug = new Map<string, Subscriber[]>();
    for (const entry of entries) {
      if (!entry.sendNow || !entry.nextSlug) continue;
      let queue = queueBySlug.get(entry.nextSlug);
      if (!queue) {
        queue = [];
        queueBySlug.set(entry.nextSlug, queue);
      }
      queue.push({ email: entry.email, name: entry.name });
    }

    let delivered = 0;
    for (const [slug, group] of queueBySlug) {
      const post = Posts.Class.find(posts, slug);
      if (post)
        delivered += (await Delivery.Class.sendPost(env, post, group))
          .delivered;
    }
    return delivered;
  }

  // The dashboard's preview: the same plan the next cron tick executes.
  static async preview(env: Env): Promise<DripPlanEntry[]> {
    const posts = await Posts.Class.load(env);
    const recipients = await Audience.Class.active(
      env,
      Audience.Class.DEFAULT_LIST,
    );
    const sendRows = await Ledger.Class.allRows(env);
    return this.plan(
      posts,
      recipients,
      sendRows,
      Number(env.CADENCE_HOURS) * 3600,
      Http.Class.nowSeconds(),
    );
  }
}

export namespace Drip {
  export const $Class = Static($Drip);
  export let Class = $Class;
}

export interface DripPlanEntry {
  email: string;
  name: string;
  nextSlug: string | null;
  sentCount: number;
  lastSentAt: number | null;
  dueAt: number;
  sendNow: boolean;
}

import { Static } from 'ivue/extras';
import { Http } from '../platform/Http';
import { Security } from '../platform/Security';
import { Turnstile } from '../platform/Turnstile';
import { Posts } from '../content/Posts';
import { Audience } from '../audience/Audience';
import { Ledger } from '../audience/Ledger';
import { Delivery } from '../delivery/Delivery';
import { Drip } from '../delivery/Drip';

// The Worker's public and operator endpoints — the surface that existed
// before the dashboard: site subscribe form, one-click unsubscribe,
// Postmark suppression sync, and the Bearer-authorized /broadcast +
// /drip operator calls.
class $PublicApi {
  static get EMAIL_PATTERN() {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  }

  static async subscribe(request: Request, env: Env): Promise<Response> {
    const body = await Http.Class.readJsonBody<{
      name: string;
      email: string;
      list: string;
      turnstileToken: string;
    }>(request);
    const address = String(body.email ?? '')
      .trim()
      .toLowerCase();
    if (!this.EMAIL_PATTERN.test(address))
      return Http.Class.json(
        { error: 'That email address does not look right.' },
        400,
      );

    // Bot gate — enforced as soon as TURNSTILE_SECRET is set; the form
    // sends the widget token as turnstileToken. Fails closed.
    if (env.TURNSTILE_SECRET) {
      const human = await Turnstile.Class.verify(
        body.turnstileToken,
        request.headers.get('CF-Connecting-IP'),
        env,
      );
      if (!human)
        return Http.Class.json(
          { error: 'Verification failed — try again.' },
          403,
        );
    }

    await Audience.Class.enroll(
      env,
      address,
      String(body.name ?? '')
        .trim()
        .slice(0, 80),
      String(body.list ?? '').trim() || Audience.Class.DEFAULT_LIST,
    );
    return Http.Class.json({ ok: true });
  }

  static async unsubscribe(url: URL, env: Env): Promise<Response> {
    const address = (url.searchParams.get('email') ?? '').toLowerCase();
    const token = url.searchParams.get('token') ?? '';
    const expected = address
      ? await Security.Class.unsubscribeToken(address, env)
      : '';
    if (
      !address ||
      !(await Security.Class.timingSafeEqualStrings(token, expected))
    )
      return new Response('Invalid unsubscribe link.', { status: 400 });

    await Audience.Class.suppress(env, address);

    return Http.Class.html(
      `<!doctype html><meta charset="utf-8"><title>Unsubscribed</title>
       <body style="font-family:system-ui;max-width:32rem;margin:15vh auto;padding:0 1rem;color:#1c2432">
       <h1 style="font-size:1.4rem">You're unsubscribed.</h1>
       <p>No more emails from the ivue newsletter. Changed your mind?
       Sign up again any time at <a href="${env.SITE_ORIGIN}">ivue.dev</a>.</p>`,
    );
  }

  static async broadcast(request: Request, env: Env): Promise<Response> {
    if (!(await Security.Class.bearerAuthorized(request, env)))
      return Http.Class.json({ error: 'Unauthorized' }, 401);

    const body = await Http.Class.readJsonBody<{ slug: string; list: string }>(
      request,
    );
    const slug = String(body.slug ?? '');
    const posts = await Posts.Class.load(env);
    const post = Posts.Class.find(posts, slug);
    if (!post)
      return Http.Class.json({ error: `Unknown post slug: ${slug}` }, 400);

    const recipients = await Audience.Class.active(
      env,
      String(body.list ?? '').trim() || Audience.Class.DEFAULT_LIST,
    );
    const alreadySent = await Ledger.Class.sentSetForSlug(env, post.slug);
    const due = recipients.filter(
      (recipient) => !alreadySent.has(recipient.email),
    );

    const report = await Delivery.Class.sendPost(env, post, due);
    return Http.Class.json({
      ok: true,
      slug: post.slug,
      recipients: report.delivered,
      skippedAsRepeat: recipients.length - due.length,
    });
  }

  // The cron's exact pass, runnable on demand — same auth as /broadcast.
  static async drip(request: Request, env: Env): Promise<Response> {
    if (!(await Security.Class.bearerAuthorized(request, env)))
      return Http.Class.json({ error: 'Unauthorized' }, 401);
    const delivered = await Drip.Class.run(env);
    return Http.Class.json({ ok: true, delivered });
  }

  // Postmark SubscriptionChange webhook: any suppression on their side
  // (their footer link, hard bounce, spam complaint) lands in OUR
  // unsubscribes table, and a reactivation clears it — D1 stays the
  // single source of truth. Configure in Postmark: newsletter stream →
  // Webhooks → Subscription change, with Basic auth postmark/ADMIN_SECRET.
  static async postmarkWebhook(request: Request, env: Env): Promise<Response> {
    if (!(await Security.Class.basicAuthorized(request, env)))
      return Http.Class.json({ error: 'Unauthorized' }, 401);

    const event = await Http.Class.readJsonBody<{
      RecordType: string;
      Recipient: string;
      SuppressSending: boolean;
      SuppressionReason: string;
    }>(request);
    if (event.RecordType !== 'SubscriptionChange' || !event.Recipient)
      return Http.Class.json({ ok: true, ignored: true });

    const address = event.Recipient.toLowerCase();
    if (event.SuppressSending) await Audience.Class.suppress(env, address);
    else await Audience.Class.unsuppress(env, address);
    console.error(
      JSON.stringify({
        event: 'postmark_suppression_sync',
        recipient: address,
        suppressed: Boolean(event.SuppressSending),
        reason: event.SuppressionReason ?? null,
      }),
    );
    return Http.Class.json({ ok: true });
  }
}

export namespace PublicApi {
  export const $Class = Static($PublicApi);
  export let Class = $Class;
}

import { Static } from 'ivue/extras';
import { Http } from '../platform/Http';
import { Security } from '../platform/Security';
import { Posts } from '../content/Posts';
import { Audience } from '../audience/Audience';
import { Ledger } from '../audience/Ledger';
import { Delivery } from '../delivery/Delivery';
import { Drip } from '../delivery/Drip';

// The dashboard's JSON API — every /admin/* route, all behind the same
// timing-safe Bearer [redacted] check. The dashboard is a pure client
// of this surface: nothing here exists for the dashboard's convenience
// that an operator couldn't equally drive with curl.
class $AdminApi {
  static async handle(
    request: Request,
    url: URL,
    env: Env,
  ): Promise<Response> {
    if (!(await Security.Class.bearerAuthorized(request, env)))
      return Http.Class.json({ error: 'Unauthorized' }, 401);

    const route = `${request.method} ${url.pathname}`;
    switch (route) {
      case 'GET /admin/subscribers':
        return this.subscribers(url, env);
      case 'GET /admin/subscriber':
        return this.subscriber(url, env);
      case 'POST /admin/subscribers/add':
        return this.add(request, env);
      case 'POST /admin/subscribers/unsubscribe':
        return this.unsubscribe(request, env);
      case 'POST /admin/subscribers/resubscribe':
        return this.resubscribe(request, env);
      case 'POST /admin/subscribers/remove':
        return this.remove(request, env);
      case 'POST /admin/send':
        return this.send(request, env);
      case 'GET /admin/posts':
        return this.posts(env);
      case 'GET /admin/preview':
        return this.preview(url, env);
      case 'GET /admin/drip-preview':
        return this.dripPreview(env);
      case 'GET /admin/lists':
        return this.lists(env);
      case 'GET /admin/stats':
        return this.stats(env);
      default:
        return Http.Class.notFound();
    }
  }

  static async subscribers(url: URL, env: Env): Promise<Response> {
    const page = await Audience.Class.page(env, {
      list: url.searchParams.get('list') ?? '',
      search: url.searchParams.get('search') ?? '',
      limit: Number(url.searchParams.get('limit') ?? 50),
      offset: Number(url.searchParams.get('offset') ?? 0),
    });
    return Http.Class.json(page);
  }

  static async subscriber(url: URL, env: Env): Promise<Response> {
    const address = (url.searchParams.get('email') ?? '').toLowerCase();
    if (!address) return Http.Class.json({ error: 'email required' }, 400);
    const [memberships, history] = await Promise.all([
      Audience.Class.memberships(env, address),
      Ledger.Class.historyFor(env, address),
    ]);
    if (!memberships.length)
      return Http.Class.json({ error: 'No such subscriber' }, 404);
    return Http.Class.json({ email: address, memberships, history });
  }

  static async add(request: Request, env: Env): Promise<Response> {
    const body = await Http.Class.readJsonBody<{
      email: string;
      name: string;
      list: string;
    }>(request);
    const address = String(body.email ?? '')
      .trim()
      .toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(address))
      return Http.Class.json({ error: 'Invalid email address.' }, 400);
    await Audience.Class.enroll(
      env,
      address,
      String(body.name ?? '')
        .trim()
        .slice(0, 80),
      String(body.list ?? '').trim() || Audience.Class.DEFAULT_LIST,
    );
    return Http.Class.json({ ok: true, email: address });
  }

  static async unsubscribe(request: Request, env: Env): Promise<Response> {
    const addresses = await this.readAddresses(request);
    await Audience.Class.suppressMany(env, addresses);
    return Http.Class.json({ ok: true, affected: addresses.length });
  }

  static async resubscribe(request: Request, env: Env): Promise<Response> {
    const addresses = await this.readAddresses(request);
    await Audience.Class.unsuppressMany(env, addresses);
    return Http.Class.json({ ok: true, affected: addresses.length });
  }

  static async remove(request: Request, env: Env): Promise<Response> {
    const body = await Http.Class.readJsonBody<{
      emails: string[];
      purgeSends: boolean;
    }>(request);
    const addresses = this.normalizeAddresses(body.emails);
    await Audience.Class.removeMany(env, addresses, Boolean(body.purgeSends));
    return Http.Class.json({ ok: true, affected: addresses.length });
  }

  // Targeted send: one post to explicit recipients. Writes the same
  // ledger as the drip and /broadcast, so a repeat is refused unless
  // `force` explicitly erases the ledger rows first.
  static async send(request: Request, env: Env): Promise<Response> {
    const body = await Http.Class.readJsonBody<{
      slug: string;
      emails: string[];
      force: boolean;
    }>(request);
    const slug = String(body.slug ?? '');
    const addresses = this.normalizeAddresses(body.emails);
    if (!addresses.length)
      return Http.Class.json({ error: 'emails required' }, 400);
    const catalog = await Posts.Class.load(env);
    const post = Posts.Class.find(catalog, slug);
    if (!post)
      return Http.Class.json({ error: `Unknown post slug: ${slug}` }, 400);

    if (body.force) await Ledger.Class.erase(env, addresses, post.slug);
    const alreadySent = await Ledger.Class.sentSetForSlug(env, post.slug);
    const skipped = addresses.filter((address) => alreadySent.has(address));
    const due = addresses
      .filter((address) => !alreadySent.has(address))
      .map((address) => ({ email: address, name: '' }));

    const report = await Delivery.Class.sendPost(env, post, due);
    return Http.Class.json({
      ok: true,
      slug: post.slug,
      delivered: report.delivered,
      outcomes: report.outcomes,
      skippedAsRepeat: skipped,
    });
  }

  static async posts(env: Env): Promise<Response> {
    const catalog = await Posts.Class.load(env);
    return Http.Class.json(Posts.Class.summaries(catalog));
  }

  // The exact email a subscriber receives, for the dashboard's preview
  // iframe — unsubscribe placeholder neutralized.
  static async preview(url: URL, env: Env): Promise<Response> {
    const slug = url.searchParams.get('slug') ?? '';
    const catalog = await Posts.Class.load(env);
    const post = Posts.Class.find(catalog, slug);
    if (!post)
      return Http.Class.json({ error: `Unknown post slug: ${slug}` }, 404);
    return Http.Class.html(
      post.emailHtml.replaceAll('{{UNSUBSCRIBE_URL}}', '#unsubscribe-preview'),
    );
  }

  static async dripPreview(env: Env): Promise<Response> {
    return Http.Class.json({
      cadenceHours: Number(env.CADENCE_HOURS),
      entries: await Drip.Class.preview(env),
    });
  }

  static async lists(env: Env): Promise<Response> {
    return Http.Class.json(await Audience.Class.lists(env));
  }

  static async stats(env: Env): Promise<Response> {
    const [lists, signups, perPost, totalSends] = await Promise.all([
      Audience.Class.lists(env),
      Audience.Class.signupsByDay(env, 60),
      Ledger.Class.statsPerPost(env),
      Ledger.Class.totalSends(env),
    ]);
    return Http.Class.json({ lists, signups, perPost, totalSends });
  }

  static async readAddresses(request: Request): Promise<string[]> {
    const body = await Http.Class.readJsonBody<{ emails: string[] }>(request);
    return this.normalizeAddresses(body.emails);
  }

  static normalizeAddresses(emails: unknown): string[] {
    if (!Array.isArray(emails)) return [];
    return [
      ...new Set(
        emails
          .map((email) => String(email).trim().toLowerCase())
          .filter(Boolean),
      ),
    ];
  }
}

export namespace AdminApi {
  export const $Class = Static($AdminApi);
  export let Class = $Class;
}

// ivue newsletter Worker — entry point. Routing only; every behavior
// lives on a namespace-pattern class under src/modules/ (the invar
// conventions — see ../CONVENTIONS.md).
//
// The whole design is one invariant: at most one email per (subscriber,
// post), ever. The D1 `sends` table IS the invariant; the daily cron,
// /broadcast, and the dashboard's targeted send are three writers of the
// same ledger, so none can repeat what another already delivered.
//
//   POST /subscribe        {name, email, turnstileToken} — site form → D1
//   GET  /unsubscribe      ?email=&token=      — HMAC-signed one-click out
//   POST /broadcast        {slug}   (Bearer [redacted]) — send a post NOW
//   POST /drip             (Bearer [redacted]) — run a drip pass on demand
//   POST /postmark-webhook (Basic auth)         — Postmark suppression sync
//   *    /admin/*          (Bearer [redacted]) — the dashboard's JSON API
//   cron daily                                  — each due subscriber gets
//                                                 their oldest unsent post
//
// Everything else is served from the dashboard's static assets (the
// `assets` block in wrangler.jsonc) — the admin dashboard app itself.

import { Http } from './modules/platform/Http';
import { PublicApi } from './modules/api/PublicApi';
import { AdminApi } from './modules/api/AdminApi';
import { Drip } from './modules/delivery/Drip';

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    if (request.method === 'OPTIONS')
      return Http.Class.withCors(new Response(null, { status: 204 }), env);
    try {
      if (url.pathname === '/subscribe' && request.method === 'POST')
        return Http.Class.withCors(
          await PublicApi.Class.subscribe(request, env),
          env,
        );
      if (url.pathname === '/unsubscribe' && request.method === 'GET')
        return PublicApi.Class.unsubscribe(url, env);
      if (url.pathname === '/broadcast' && request.method === 'POST')
        return PublicApi.Class.broadcast(request, env);
      if (url.pathname === '/drip' && request.method === 'POST')
        return PublicApi.Class.drip(request, env);
      if (url.pathname === '/postmark-webhook' && request.method === 'POST')
        return PublicApi.Class.postmarkWebhook(request, env);
      if (url.pathname.startsWith('/admin/'))
        return AdminApi.Class.handle(request, url, env);
      return Http.Class.notFound();
    } catch (error) {
      console.error(
        JSON.stringify({
          event: 'unhandled_error',
          path: url.pathname,
          error: String(error),
        }),
      );
      return Http.Class.withCors(
        Http.Class.json(
          { error: 'Something went wrong — try again in a minute.' },
          500,
        ),
        env,
      );
    }
  },

  async scheduled(_event, env, context): Promise<void> {
    context.waitUntil(Drip.Class.run(env));
  },
} satisfies ExportedHandler<Env>;

