/* ivue newsletter admin — dark, ivue-branded (indigo → emerald).
   Design system: 8px spacing rhythm, one accent gradient used sparingly,
   motion 150–250ms ease-out (disabled under prefers-reduced-motion). */
:root {
  --bg: #0a0d13;
  --panel: #11151e;
  --panel-raised: #151a25;
  --panel-edge: #1f2634;
  --panel-edge-soft: #1a202c;
  --text: #e2e8f4;
  --text-dim: #aab4c6;
  --muted: #76819515;
  --muted-text: #7c8698;
  --accent: #818cf8;
  --accent-strong: #6366f1;
  --accent-2: #34d399;
  --danger: #f87171;
  --radius: 12px;
  --radius-small: 8px;
  --shadow-pop: 0 12px 32px rgba(0, 0, 0, 0.45);
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font:
    15px/1.5 system-ui,
    -apple-system,
    'Segoe UI',
    sans-serif;
  -webkit-font-smoothing: antialiased;
}

/* ambient brand glow, fixed behind everything */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(42rem 22rem at 12% -8%, rgba(99, 102, 241, 0.14), transparent 60%),
    radial-gradient(36rem 20rem at 95% 0%, rgba(52, 211, 153, 0.08), transparent 60%);
  z-index: 0;
}

#app,
.shell {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  position: relative;
  z-index: 1;
}

/* ---- top bar ---- */
.topbar {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  padding: 0.65rem 1.25rem;
  border-bottom: 1px solid var(--panel-edge-soft);
  background: rgba(13, 16, 24, 0.82);
  position: sticky;
  top: 0;
  z-index: 20;
  backdrop-filter: blur(10px);
}

/* gradient hairline across the very top */
.topbar::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--accent-strong), var(--accent-2));
  opacity: 0.9;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.brand-glyph {
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 6px;
  background: linear-gradient(135deg, var(--accent-strong), var(--accent-2));
  box-shadow: 0 0 14px rgba(99, 102, 241, 0.45);
  flex: none;
}

.brand-mark {
  font-weight: 800;
  font-size: 1.15rem;
  letter-spacing: -0.01em;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.brand-sub {
  color: var(--muted-text);
  font-size: 0.85rem;
}

.tabs {
  display: flex;
  gap: 0.2rem;
  flex: 1;
  overflow-x: auto;
}

.tab {
  position: relative;
  background: none;
  border: 0;
  color: var(--muted-text);
  padding: 0.5rem 0.9rem;
  border-radius: var(--radius-small);
  cursor: pointer;
  font: inherit;
  font-weight: 600;
  transition:
    color 150ms ease-out,
    background 150ms ease-out;
}

.tab:hover {
  color: var(--text);
  background: var(--muted);
}

.tab.active {
  color: var(--text);
}

.tab.active::after {
  content: '';
  position: absolute;
  left: 0.9rem;
  right: 0.9rem;
  bottom: 0.15rem;
  height: 2px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
}

/* ---- structure ---- */
.content {
  padding: 1.75rem clamp(1rem, 3vw, 2.5rem) 3rem;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}

.gate {
  flex: 1;
  display: grid;
  place-items: center;
  padding: 2rem 1rem;
}

.card {
  background: var(--panel);
  border: 1px solid var(--panel-edge-soft);
  border-radius: var(--radius);
  padding: 1.1rem 1.35rem;
}

.view {
  animation: view-enter 220ms ease-out;
}

@keyframes view-enter {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.view-head {
  display: flex;
  align-items: baseline;
  gap: 1.25rem;
  flex-wrap: wrap;
  margin-bottom: 1.1rem;
}

h1 {
  font-size: 1.45rem;
  letter-spacing: -0.015em;
  margin: 0;
}

h2 {
  font-size: 1.02rem;
  margin: 0 0 0.6rem;
}

h3 {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;


… [7,880 characters removed from the sample] …

;
  gap: 1rem;
}

.drawer-head h2 {
  margin: 0;
  overflow-wrap: anywhere;
}

.memberships,
.history {
  list-style: none;
  margin: 0;
  padding: 0;
}

.memberships li,
.history li {
  display: flex;
  align-items: baseline;
  gap: 0.7rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--panel-edge-soft);
  flex-wrap: wrap;
}

.memberships li:last-child,
.history li:last-child {
  border-bottom: 0;
}

/* ---- posts / preview ---- */
.posts-layout {
  display: grid;
  grid-template-columns: minmax(20rem, 1fr) minmax(24rem, 1.2fr);
  gap: 1rem;
  align-items: start;
}

.posts-list td {
  white-space: normal;
}

.post-title {
  font-weight: 600;
}

.preview {
  position: sticky;
  top: 4.4rem;
  animation: view-enter 200ms ease-out;
}

.preview-frame {
  width: 100%;
  height: 70vh;
  border: 1px solid var(--panel-edge);
  border-radius: var(--radius-small);
  background: #fff;
}

/* ---- send ---- */
.send-layout {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 1rem;
  align-items: start;
}

.send-form select,
.send-form textarea {
  width: 100%;
}

.send-result {
  margin-top: 1.1rem;
  border-top: 1px solid var(--panel-edge-soft);
  padding-top: 0.7rem;
  animation: view-enter 180ms ease-out;
}

.send-result ul {
  list-style: none;
  padding: 0;
  margin: 0.4rem 0 0;
}

hr {
  border: 0;
  border-top: 1px solid var(--panel-edge-soft);
  margin: 1.2rem 0;
}

/* ---- drip / stats ---- */
.statline {
  display: flex;
  gap: 0.8rem;
  align-items: stretch;
  flex-wrap: wrap;
  margin-bottom: 1.1rem;
}

.stat {
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  background: var(--panel);
  border: 1px solid var(--panel-edge-soft);
  border-radius: var(--radius);
  padding: 0.7rem 1.05rem;
  color: var(--muted-text);
  font-size: 0.9rem;
}

.stat strong {
  color: var(--text);
  font-size: 1.45rem;
  font-weight: 750;
  letter-spacing: -0.02em;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.statline .ghost {
  align-self: center;
}

.stats-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  align-items: start;
}

.bars {
  display: flex;
  flex-direction: column;
  gap: 0.32rem;
}

.bar-row {
  display: grid;
  grid-template-columns: 6.2rem 1fr 2rem;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.85rem;
}

.bar-label {
  color: var(--muted-text);
  font-family: ui-monospace, monospace;
  font-size: 0.76rem;
}

.bar {
  height: 0.72rem;
  min-width: 3px;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--accent-strong), var(--accent-2));
  box-shadow: 0 0 8px rgba(99, 102, 241, 0.3);
}

.bar-count {
  text-align: right;
  color: var(--muted-text);
  font-variant-numeric: tabular-nums;
}

/* ---- toasts ---- */
.toasts {
  position: fixed;
  bottom: 1rem;
  right: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  z-index: 60;
}

.toast {
  background: var(--panel-raised);
  border: 1px solid var(--panel-edge);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius-small);
  padding: 0.65rem 0.95rem;
  max-width: 22rem;
  cursor: pointer;
  box-shadow: var(--shadow-pop);
  animation: toast-in 200ms ease-out;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(0.6rem);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.toast.success {
  border-left-color: var(--accent-2);
}

.toast.error {
  border-left-color: var(--danger);
}

/* ---- responsive ---- */
@media (max-width: 900px) {
  .posts-layout,
  .send-layout,
  .stats-layout {
    grid-template-columns: 1fr;
  }

  .preview {
    position: static;
  }

  .brand-sub {
    display: none;
  }
}

/* ---- reduced motion: keep it instant ---- */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

