1	// ProjectStore.ts — a global store is just an ivue class with a singleton
2	// composable. No Pinia, no defineStore, no plugin: the class IS the store,
3	// and useProjectStore() hands every caller the same instance.
4	import { reactive, ref, shallowRef } from 'vue';
5	import { Reactive } from '../../ivue';
6	
7	export interface ProjectTask {
8	  id: number;
9	  title: string;
10	  done: boolean;
11	}
12	
13	export type TaskFilter = 'all' | 'active' | 'done';
14	
15	const STORAGE_KEY = 'ivue-example-project-store';
16	
17	class $ProjectStore {
18	  // Outliving instance: the store outlives every component, so watchers
19	  // registered here use $watch/$watchEffect (the instance's own scope).
20	  constructor() {
21	    this.hydrate();
22	    this.$watchEffect(() => this.persist());
23	  }
24	
25	  get projectName() {
26	    return ref('Apollo');
27	  }
28	  get tasks() {
29	    return shallowRef<ProjectTask[]>([
30	      { id: 1, title: 'Design the flight plan', done: true },
31	      { id: 2, title: 'Fuel the first stage', done: false },
32	      { id: 3, title: 'Run the countdown checklist', done: false },
33	    ]);
34	  }
35	  get filter() {
36	    return ref<TaskFilter>('all');
37	  }
38	
39	  // DERIVED — plain getters: zero bytes per instance, and there is only
40	  // one instance anyway. Every consumer reads the same live values.
41	  get completedCount() {
42	    return this.tasks.value.filter((task) => task.done).length;
43	  }
44	  get progressPercent() {
45	    const total = this.tasks.value.length;
46	    return total === 0 ? 0 : Math.round((this.completedCount / total) * 100);
47	  }
48	  get visibleTasks(): ProjectTask[] {
49	    if (this.filter.value === 'active') {
50	      return this.tasks.value.filter((task) => !task.done);
51	    }
52	    if (this.filter.value === 'done') {
53	      return this.tasks.value.filter((task) => task.done);
54	    }
55	    return this.tasks.value;
56	  }
57	
58	  addTask(title: string) {
59	    const trimmed = title.trim();
60	    if (!trimmed) return;
61	    this.tasks.value = [
62	      ...this.tasks.value,
63	      { id: Date.now(), title: trimmed, done: false },
64	    ];
65	  }
66	
67	  toggleTask(id: number) {
68	    this.tasks.value = this.tasks.value.map((task) =>
69	      task.id === id ? { ...task, done: !task.done } : task,
70	    );
71	  }
72	
73	  setFilter(filter: TaskFilter) {
74	    this.filter.value = filter;
75	  }
76	
77	  /** Restore a previous visit's state — reload the page and it holds. */
78	  hydrate() {
79	    try {
80	      const saved = localStorage.getItem(STORAGE_KEY);
81	      if (!saved) return;
82	      const state = JSON.parse(saved);
83	      if (typeof state.projectName === 'string') {
84	        this.projectName.value = state.projectName;
85	      }
86	      if (Array.isArray(state.tasks)) this.tasks.value = state.tasks;
87	    } catch {
88	      /* corrupted storage — keep the seed state */
89	    }
90	  }
91	
92	  /** The $watchEffect in the constructor re-runs this whenever the name or
93	   *  the task list changes — its reads ARE the subscription. */
94	  persist() {
95	    const state = {
96	      projectName: this.projectName.value,
97	      tasks: this.tasks.value,
98	    };
99	    try {
100	      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
101	    } catch {
102	      /* storage unavailable — the store still works in memory */
103	    }
104	  }
105	}
106	
107	export namespace ProjectStore {
108	  export const $Class = $ProjectStore; // raw — children `extends` this
109	  export let Class = Reactive($Class); // reactive — you `new` this
110	  export type Instance = typeof Class.Instance; // defineExpose type & reactive() interop
111	}
112	
113	let store: InstanceType<typeof ProjectStore.Class> | undefined;
114	
115	/** The store composable: every caller receives the SAME instance. */
116	export function useProjectStore() {
117	  return (store ??= new ProjectStore.Class());
118	}
119	
120	/**
121	 * Optional `reactive()` view of the same singleton — refs auto-unwrap on
122	 * read AND write, so consumers drop every `.value`. The cast through
123	 * `ProjectStore.Instance` is load-bearing: it strips the readonly that TS
124	 * puts on get-only accessors, so writes typecheck as they behave.
125	 */
126	export function useProjectStoreReactive() {
127	  return reactive(useProjectStore() as ProjectStore.Instance);
